import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"Lesson 2: What Can Codex Do for You? (Demo Session)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-1/lesson-2.md","filePath":"en/modules/module-1/lesson-2.md"}'),i={name:"en/modules/module-1/lesson-2.md"};function s(r,e,d,l,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="lesson-2-what-can-codex-do-for-you-demo-session" tabindex="-1">Lesson 2: What Can Codex Do for You? (Demo Session) <a class="header-anchor" href="#lesson-2-what-can-codex-do-for-you-demo-session" aria-label="Permalink to &quot;Lesson 2: What Can Codex Do for You? (Demo Session)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand Codex&#39;s capabilities and application scenarios through real-world examples ⏱️ <strong>Estimated Time</strong>: 20 minutes 🎯 <strong>Teaching Rhythm</strong>: Demo-focused, watch and discuss</p></blockquote><hr><h2 id="i-opening-let-s-see-how-capable-codex-really-is" tabindex="-1">I. Opening: Let&#39;s See How Capable Codex Really Is <a class="header-anchor" href="#i-opening-let-s-see-how-capable-codex-really-is" aria-label="Permalink to &quot;I. Opening: Let&#39;s See How Capable Codex Really Is&quot;">​</a></h2><p>Before we dive into the formal content, I want to show you a few real cases. These aren&#39;t &quot;demo tricks&quot; — these are things ordinary people actually use Codex to get done.</p><hr><h2 id="ii-programming-development-more-than-just-writing-code" tabindex="-1">II. Programming &amp; Development: More Than Just Writing Code <a class="header-anchor" href="#ii-programming-development-more-than-just-writing-code" aria-label="Permalink to &quot;II. Programming &amp; Development: More Than Just Writing Code&quot;">​</a></h2><h3 id="case-1-fixing-a-bug" tabindex="-1">Case 1: Fixing a Bug <a class="header-anchor" href="#case-1-fixing-a-bug" aria-label="Permalink to &quot;Case 1: Fixing a Bug&quot;">​</a></h3><p><strong>User background</strong>: Xiao Wang, a college student, encountered a Python error while working on a course project. He spent two days searching online but couldn&#39;t solve it.</p><p><strong>What he did</strong>:</p><ol><li>Copied the error message and pasted it into Codex</li><li>Dragged the relevant code files into Codex&#39;s workspace</li><li>Said: &quot;This function throws &#39;IndexError: list index out of range&#39;. Help me find the cause and fix it.&quot;</li></ol><p><strong>Result</strong>: Codex found the issue in 30 seconds — the list index was out of bounds because the code didn&#39;t check if the list was empty. It provided the fixed code and explained why the error occurred.</p><blockquote><p>💡 <strong>Key takeaway</strong>: You don&#39;t need to know what &quot;index out of bounds&quot; means. You just need to tell Codex &quot;it&#39;s broken, help me fix it.&quot;</p></blockquote><h3 id="case-2-from-an-idea-to-a-complete-website" tabindex="-1">Case 2: From an Idea to a Complete Website <a class="header-anchor" href="#case-2-from-an-idea-to-a-complete-website" aria-label="Permalink to &quot;Case 2: From an Idea to a Complete Website&quot;">​</a></h3><p><strong>User background</strong>: Xiao Li, a marketing specialist, wanted to build a product landing page but didn&#39;t know frontend development.</p><p><strong>What he did</strong>:</p><ol><li>Opened Codex and said: &quot;Help me build a single-page website to introduce my product — a smart water bottle&quot;</li><li>Codex generated a complete HTML page with a Hero section, feature introductions, and user testimonials</li><li>Xiao Li said: &quot;Change the main color to blue and add a contact form&quot;</li><li>After Codex made the modifications, Xiao Li saved the file as <code>index.html</code> and double-clicked to view it in a browser</li></ol><p><strong>Result</strong>: A frontend task that would normally take days was completed in 30 minutes.</p><h3 id="case-3-refactoring-messy-code" tabindex="-1">Case 3: Refactoring Messy Code <a class="header-anchor" href="#case-3-refactoring-messy-code" aria-label="Permalink to &quot;Case 3: Refactoring Messy Code&quot;">​</a></h3><p><strong>User background</strong>: Lao Zhang, an operations engineer, inherited a Python script written by a predecessor — long, messy, and hard to understand.</p><p><strong>What he did</strong>:</p><ol><li>Dragged the file into Codex</li><li>Said: &quot;This code is too messy. Refactor it, add comments, and make it readable for others.&quot;</li></ol><p><strong>Result</strong>: Codex split the code into clear functions, added docstrings, and wrote usage instructions.</p><hr><h2 id="iii-office-productivity-organizing-materials-generating-content" tabindex="-1">III. Office Productivity: Organizing Materials &amp; Generating Content <a class="header-anchor" href="#iii-office-productivity-organizing-materials-generating-content" aria-label="Permalink to &quot;III. Office Productivity: Organizing Materials &amp; Generating Content&quot;">​</a></h2><h3 id="case-4-organizing-a-messy-downloads-folder" tabindex="-1">Case 4: Organizing a Messy Downloads Folder <a class="header-anchor" href="#case-4-organizing-a-messy-downloads-folder" aria-label="Permalink to &quot;Case 4: Organizing a Messy Downloads Folder&quot;">​</a></h3><p><strong>User background</strong>: Xiao Chen, an administrative staff member, had hundreds of files in her computer&#39;s &quot;Downloads&quot; folder, all jumbled together.</p><p><strong>What she did</strong>:</p><ol><li>Set the &quot;Downloads&quot; folder as Codex&#39;s workspace</li><li>Said: &quot;Help me organize this folder. Classify by file type: put images in an <code>images</code> folder, PDFs in <code>documents</code>, and Excel files in <code>spreadsheets</code>.&quot;</li><li>Codex automatically created subfolders and moved the files in.</li></ol><p><strong>Result</strong>: In 5 minutes, a chaotic folder became neatly organized.</p><h3 id="case-5-generating-meeting-minutes" tabindex="-1">Case 5: Generating Meeting Minutes <a class="header-anchor" href="#case-5-generating-meeting-minutes" aria-label="Permalink to &quot;Case 5: Generating Meeting Minutes&quot;">​</a></h3><p><strong>User background</strong>: Ajie, a project manager, attends various meetings every day and finds writing minutes exhausting.</p><p><strong>What he did</strong>:</p><ol><li>Sent Codex the transcript of a meeting recording (or text converted from speech)</li><li>Said: &quot;Based on this meeting record, generate a structured meeting minutes document, including: agenda items, key discussion points, resolutions, and action items (with assigned owners).&quot;</li></ol><p><strong>Result</strong>: Codex produced a well-formatted meeting minutes document, even better than what he would have written himself.</p><h3 id="case-6-batch-processing-excel-data" tabindex="-1">Case 6: Batch Processing Excel Data <a class="header-anchor" href="#case-6-batch-processing-excel-data" aria-label="Permalink to &quot;Case 6: Batch Processing Excel Data&quot;">​</a></h3><p><strong>User background</strong>: Xiao Liu, a financial analyst, needs to produce sales reports every month.</p><p><strong>What he did</strong>:</p><ol><li>Dragged an Excel file into Codex</li><li>Said: &quot;Analyze this sales data, find the monthly trends for each product, and generate a summary report.&quot;</li><li>Codex used Python to read the Excel file, performed data analysis, and generated charts.</li></ol><p><strong>Result</strong>: A manual task that used to take 2 hours was completed in 5 minutes.</p><hr><h2 id="iv-data-analysis-automation-report-generation" tabindex="-1">IV. Data Analysis: Automation + Report Generation <a class="header-anchor" href="#iv-data-analysis-automation-report-generation" aria-label="Permalink to &quot;IV. Data Analysis: Automation + Report Generation&quot;">​</a></h2><h3 id="case-7-from-csv-to-visual-reports" tabindex="-1">Case 7: From CSV to Visual Reports <a class="header-anchor" href="#case-7-from-csv-to-visual-reports" aria-label="Permalink to &quot;Case 7: From CSV to Visual Reports&quot;">​</a></h3><p><strong>User background</strong>: Xiao Zhou, a social media operator, needs to export data from a backend system and analyze it.</p><p><strong>What she did</strong>:</p><ol><li>Exported the CSV file from the backend</li><li>Dragged it into Codex and said: &quot;Analyze this data. Tell me which article got the most views and which posting time slots performed best.&quot;</li><li>Codex generated analysis conclusions and visual charts.</li></ol><h3 id="case-8-comparing-two-datasets" tabindex="-1">Case 8: Comparing Two Datasets <a class="header-anchor" href="#case-8-comparing-two-datasets" aria-label="Permalink to &quot;Case 8: Comparing Two Datasets&quot;">​</a></h3><p><strong>User background</strong>: Lao Li, an e-commerce operator, needs to compare sales data between two quarters.</p><p><strong>What he did</strong>:</p><ol><li>Dragged both quarters&#39; CSV files into Codex</li><li>Said: &quot;Compare these two files. Find the fastest-growing categories and the fastest-declining categories.&quot;</li><li>Codex completed the comparison and generated conclusions.</li></ol><hr><h2 id="v-everyday-tasks-not-just-professional-scenarios" tabindex="-1">V. Everyday Tasks: Not Just &quot;Professional&quot; Scenarios <a class="header-anchor" href="#v-everyday-tasks-not-just-professional-scenarios" aria-label="Permalink to &quot;V. Everyday Tasks: Not Just &quot;Professional&quot; Scenarios&quot;">​</a></h2><h3 id="case-9-organizing-photos" tabindex="-1">Case 9: Organizing Photos <a class="header-anchor" href="#case-9-organizing-photos" aria-label="Permalink to &quot;Case 9: Organizing Photos&quot;">​</a></h3><p><strong>User background</strong>: Xiao Wu, a photography enthusiast, has thousands of photos on his phone and doesn&#39;t know how to categorize them.</p><p><strong>What he did</strong>:</p><ol><li>Dragged the photos folder into Codex</li><li>Said: &quot;Organize these photos into different folders by shooting date, one folder per month.&quot;</li><li>Codex read the EXIF data and categorized by date.</li></ol><h3 id="case-10-analyzing-disk-space" tabindex="-1">Case 10: Analyzing Disk Space <a class="header-anchor" href="#case-10-analyzing-disk-space" aria-label="Permalink to &quot;Case 10: Analyzing Disk Space&quot;">​</a></h3><p><strong>User background</strong>: Lao Zhao&#39;s computer was nearly full, and he wanted to know what was taking up space.</p><p><strong>What he did</strong>:</p><ol><li>Said: &quot;Help me analyze the disk space usage of this folder and list the top 10 largest files.&quot;</li><li>Codex executed system commands and generated a report.</li></ol><h3 id="case-11-translating-and-polishing-documents" tabindex="-1">Case 11: Translating and Polishing Documents <a class="header-anchor" href="#case-11-translating-and-polishing-documents" aria-label="Permalink to &quot;Case 11: Translating and Polishing Documents&quot;">​</a></h3><p><strong>User background</strong>: Xiao Zheng needed to translate a Chinese report into English.</p><p><strong>What he did</strong>:</p><ol><li>Dragged the document into Codex</li><li>Said: &quot;Translate this Chinese report into English, maintaining a formal business style.&quot;</li></ol><hr><h2 id="vi-non-technical-people-are-also-using-it" tabindex="-1">VI. Non-Technical People Are Also Using It <a class="header-anchor" href="#vi-non-technical-people-are-also-using-it" aria-label="Permalink to &quot;VI. Non-Technical People Are Also Using It&quot;">​</a></h2><p>Here&#39;s something you might not know: <strong>Inside OpenAI, non-technical staff also use Codex for their work.</strong></p><table tabindex="0"><thead><tr><th>Role</th><th>Use Case</th></tr></thead><tbody><tr><td>Lawyer</td><td>Organizing contract clauses, extracting key dates and amounts</td></tr><tr><td>Recruiter</td><td>Screening resumes, generating interview questions</td></tr><tr><td>Operations</td><td>Analyzing user feedback data, generating weekly reports</td></tr><tr><td>Designer</td><td>Generating CSS styles, adjusting design parameters</td></tr><tr><td>Teacher</td><td>Creating exams, grading assignments, generating teaching materials</td></tr></tbody></table><p><strong>What does this mean?</strong> It means Codex is not a &quot;programmer-only tool.&quot; It&#39;s an &quot;efficient tool that anyone can use.&quot;</p><hr><h2 id="vii-your-turn-to-try" tabindex="-1">VII. Your Turn to Try <a class="header-anchor" href="#vii-your-turn-to-try" aria-label="Permalink to &quot;VII. Your Turn to Try&quot;">​</a></h2><p>Now it&#39;s your turn to try it yourself.</p><p><strong>Task</strong>: Get Codex to help you with something small.</p><ol><li>Open Codex</li><li>Enter any one of the following prompts (pick the one you find most useful): <ul><li>&quot;Help me write an email thanking a client for yesterday&#39;s order&quot;</li><li>&quot;Help me create a weekly work plan template&quot;</li><li>&quot;Help me generate an HTML page for a to-do list&quot;</li></ul></li><li>See what Codex produces</li><li>If you&#39;re not satisfied, try adding another request, like &quot;Make the tone more formal.&quot;</li></ol><blockquote><p>💡 <strong>Tip</strong>: Don&#39;t aim for a perfect result. The goal of this section is to let you experience &quot;commanding AI with natural language.&quot;</p></blockquote><hr><h2 id="viii-summary" tabindex="-1">VIII. Summary <a class="header-anchor" href="#viii-summary" aria-label="Permalink to &quot;VIII. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability Category</th><th>Typical Scenarios</th></tr></thead><tbody><tr><td>Programming &amp; Development</td><td>Writing features, fixing bugs, refactoring code</td></tr><tr><td>Office Productivity</td><td>Organizing materials, generating content, making PPTs</td></tr><tr><td>Data Analysis</td><td>Automating data processing, generating reports</td></tr><tr><td>Everyday Tasks</td><td>Organizing files, analyzing disk space, translating documents</td></tr></tbody></table><p><strong>Core insight</strong>: Codex is not a &quot;search engine on steroids.&quot; It&#39;s a &quot;smart assistant&quot; that can directly operate your files and systems.</p><hr><h2 id="ix-post-lesson-thinking" tabindex="-1">IX. Post-Lesson Thinking <a class="header-anchor" href="#ix-post-lesson-thinking" aria-label="Permalink to &quot;IX. Post-Lesson Thinking&quot;">​</a></h2><ol><li>Which case shown today made you think &quot;this would be useful for me&quot;?</li><li>What repetitive tasks in your current work could you hand over to Codex?</li><li>What do you think is Codex&#39;s biggest pain point it could solve for you?</li></ol><blockquote><p>💡 <strong>Hint</strong>: Bring these questions into the next lesson. We&#39;ll compare Codex with other tools to help you position its value more clearly.</p></blockquote><hr><h2 id="x-next-step" tabindex="-1">X. Next Step <a class="header-anchor" href="#x-next-step" aria-label="Permalink to &quot;X. Next Step&quot;">​</a></h2><p><a href="./lesson-3.html">→ Lesson 3: Codex vs Other Tools</a></p>',86)])])}const p=t(i,[["render",s]]);export{c as __pageData,p as default};
